/**
 * Creates audit details containing issues, insights table, and artifact tree based on configuration.
 * Assembles comprehensive output details for bundle analysis reporting.
 */
export function createAuditOutputDetails(
  issues: Issue[],
  statsSlice: UnifiedStats,
  config: BundleStatsConfig,
): AuditDetails {
  const details: AuditDetails = {
    issues,
  };

  if (
    config.insightsTable &&
    config.insightsTable.groups &&
    config.insightsTable.groups.length > 0
  ) {
    console.time('📊 CREATE_INSIGHTS_TABLE');
    details.table = createInsightsTable(statsSlice, config.insightsTable);
    console.timeEnd('📊 CREATE_INSIGHTS_TABLE');
  }

  // Check if dependency tree is enabled (default: enabled if config exists)
  const isTreeEnabled =
    config.dependencyTree &&
    typeof config.dependencyTree === 'object' &&
    (!('enabled' in config.dependencyTree) ||
      config.dependencyTree.enabled !== false);

  if (isTreeEnabled && typeof config.dependencyTree === 'object') {
    console.time('🌳 CREATE_TREE');
    details.trees = [
      createTree(statsSlice, {
        title: config.slug,
        mode: config.dependencyTree.mode ?? 'onlyMatching',
        pruning: config.dependencyTree.pruning ?? {},
        groups: config.dependencyTree.groups ?? [],
        selection: config.selection, // Pass selection config for onlyMatching filtering
      }),
    ];
    console.timeEnd('🌳 CREATE_TREE');
  }

  return details;
}

import {
  extractConcreteSegments,
  extractPathSlice,
  findSegmentIndex,
  normalizePathForMatching,
  splitPathSegments,
} from './grouping.js';

// Regex cache to avoid recreating the same regex patterns
const REGEX_CACHE = new Map<string, RegExp>();

function getCachedRegex(pattern: string): RegExp {
  const cached = REGEX_CACHE.get(pattern);
  if (cached) {
    return cached;
  }

  const regex = new RegExp(`${pattern}\\/([^\\/]+)`);
  REGEX_CACHE.set(pattern, regex);
  return regex;
}

export function removeFileExtension(name: string): string {
  return name.replace(/\.(js|ts|jsx|tsx|css|scss|json)$/, '');
}

export function isGenericName(name: string): boolean {
  return name === 'index' || name === 'main' || name === '';
}

export function extractScopedPackage(
  path: string,
): { scope: string; package?: string } | null {
  const match = path.match(/@([^/]+)(?:\/([^/]+))?/);
  if (match) {
    return {
      scope: match[1]!,
      package: match[2],
    };
  }
  return null;
}

export function extractMeaningfulPathPart(path: string): string | null {
  const parts = splitPathSegments(path.replace(/^\.\//, ''));

  if (parts.length === 0) {
    return null;
  }

  const lastPart = parts.at(-1);
  if (lastPart) {
    const withoutExt = removeFileExtension(lastPart);
    if (withoutExt && !isGenericName(withoutExt)) {
      return withoutExt;
    }
  }

  if (parts.length > 1) {
    const secondLast = parts.at(-2);
    if (secondLast && !isGenericName(secondLast)) {
      return secondLast;
    }
  }

  return null;
}

export function cleanupGroupName(groupName: string): string {
  const scopedPackage = extractScopedPackage(groupName);
  if (scopedPackage) {
    return scopedPackage.package
      ? `@${scopedPackage.scope}/${scopedPackage.package}`
      : `@${scopedPackage.scope}`;
  }

  const segments = splitPathSegments(groupName);
  if (segments.length === 0) {
    return groupName;
  }

  // For scoped packages, try to extract the scope and package
  for (let i = 0; i < segments.length; i++) {
    const segment = segments[i];
    if (!segment) {
      continue;
    }

    // Handle scoped packages like @angular/router
    if (segment.startsWith('@') && i + 1 < segments.length) {
      const scopeName = segment.slice(1);
      const packageName = segments[i + 1];
      return packageName ? `@${scopeName}/${packageName}` : `@${scopeName}`;
    }
  }

  // Extract the last meaningful segment (the actual package/folder name)
  for (let i = segments.length - 1; i >= 0; i--) {
    const segment = segments[i];
    if (!segment || isGenericName(segment)) {
      continue;
    }

    // Return the first meaningful segment we find from the end
    return segment;
  }

  const withoutExt = removeFileExtension(groupName);
  if (isGenericName(withoutExt)) {
    return groupName;
  }

  return withoutExt || groupName;
}

export function extractGroupKeyFromPattern(
  filePath: string,
  pattern: string,
  maxDepth?: number,
): string | null {
  const normalizedPath = normalizePathForMatching(filePath);
  const concreteSegments = extractConcreteSegments(pattern);

  if (concreteSegments.length === 0) {
    return extractMeaningfulPathPart(normalizedPath);
  }

  if (maxDepth && maxDepth > 0 && concreteSegments.length > 0) {
    const keyPart = concreteSegments[0]!;
    const keyIndex = findSegmentIndex(filePath, keyPart);

    if (keyIndex !== -1) {
      return extractPathSlice(filePath, keyIndex, maxDepth);
    }
  }

  for (const segment of concreteSegments) {
    const regex = getCachedRegex(segment); // Use cached regex
    const match = filePath.match(regex) || normalizedPath.match(regex);

    if (match?.[1]) {
      const extracted = match[1];
      const cleaned = removeFileExtension(extracted);
      if (cleaned && !isGenericName(cleaned)) {
        return cleaned;
      }
    }
  }

  return null;
}

export function deriveGroupTitle(
  path: string,
  patterns: readonly string[],
  fallbackTitle: string,
): string {
  for (const pattern of patterns) {
    const concreteSegments = extractConcreteSegments(pattern);

    if (concreteSegments.includes(fallbackTitle)) {
      return fallbackTitle;
    }

    const groupName = extractGroupKeyFromPattern(path, pattern);
    if (groupName) {
      return cleanupGroupName(groupName);
    }
  }

  return fallbackTitle;
}

import { minimatch } from 'minimatch';
import type { GroupingRule, LogicalGroupingRule } from '../../types.js';
import {
  cleanupGroupName,
  deriveGroupTitle,
  extractGroupKeyFromPattern,
} from './formatting.js';
import type { ArtefactType, StatsNodeValues } from './types.js';

export type PatternMatcher = (path: string) => boolean;

// Pattern cache to avoid recompiling the same patterns
const PATTERN_CACHE = new Map<string, PatternMatcher>();

/**
 * Normalizes patterns from string | PatternList to readonly string[].
 */
function normalizePatterns(
  patterns?: string | readonly string[],
): readonly string[] {
  if (!patterns) {
    return [];
  }

  const normalizedArray = typeof patterns === 'string' ? [patterns] : patterns;

  // Filter out any undefined, null, or empty string values
  return normalizedArray.filter(
    (pattern): pattern is string =>
      typeof pattern === 'string' && pattern.trim() !== '',
  );
}

export type MatchOptions = {
  matchBase?: boolean;
  normalizeRelativePaths?: boolean;
};

export type GroupData = Omit<StatsNodeValues, 'type' | 'path'> & {
  title: string;
  type: 'group';
};

export type GroupManager<T extends GroupData = GroupData> = {
  groups: Map<string, T>;
  findOrCreateGroup: (
    key: string,
    rule: LogicalGroupingRule,
    defaultTitle?: string,
  ) => T;
  getAllGroups: () => T[];
  getGroupsWithData: () => T[];
};

export type StatsTreeNode = {
  children: StatsTreeNode[];
  name: string;
  values: StatsNodeValues;
};

export type StatsTree = {
  root: StatsTreeNode;
};

const DEFAULT_GROUP_NAME = 'Group';

export function splitPathSegments(path: string): string[] {
  return path.split('/').filter(part => part !== '');
}

export function normalizePathForMatching(path: string): string {
  return path.replace(/\.\.\//g, '').replace(/^\/+/, '');
}

/**
 * Compiles pattern into cached matcher function. Avoids recompilation overhead.
 */
export function compilePattern(
  pattern: string,
  options: MatchOptions = {},
): PatternMatcher {
  // Create cache key from pattern and options
  const cacheKey = `${pattern}|${JSON.stringify(options)}`;

  // Return cached pattern if available
  const cached = PATTERN_CACHE.get(cacheKey);
  if (cached) {
    return cached;
  }

  // Compile new pattern
  const matcher = (path: string) => {
    const minimatchOptions = options.matchBase ? { matchBase: true } : {};
    if (minimatch(path, pattern, minimatchOptions)) {
      return true;
    }
    if (options.normalizeRelativePaths) {
      const normalizedPath = normalizePathForMatching(path);
      return minimatch(normalizedPath, pattern, minimatchOptions);
    }
    return false;
  };

  // Cache and return
  PATTERN_CACHE.set(cacheKey, matcher);
  return matcher;
}

/**
 * Checks if path matches a GroupingRule using include/exclude logic
 */
function matchesGroupingRule(
  path: string,
  rule: GroupingRule,
  options: MatchOptions = {},
): boolean {
  const includePatterns = normalizePatterns(rule.includeInputs);
  const excludePatterns = normalizePatterns(rule.excludeInputs);

  return evaluatePathWithIncludeExclude(
    path,
    includePatterns,
    excludePatterns,
    options,
  );
}

/**
 * Separates patterns into include and exclude arrays. Exclude patterns start with !
 * @deprecated - Use the new include/exclude GroupingRule format instead
 */
function separateIncludeExcludePatterns(patterns: readonly string[]): {
  includePatterns: string[];
  excludePatterns: string[];
} {
  const includePatterns: string[] = [];
  const excludePatterns: string[] = [];

  for (const pattern of patterns) {
    if (pattern.startsWith('!')) {
      excludePatterns.push(pattern.slice(1)); // Remove ! prefix
    } else {
      includePatterns.push(pattern);
    }
  }

  return { includePatterns, excludePatterns };
}

/**
 * Evaluates path against include/exclude patterns using the same logic as selection system
 */
function evaluatePathWithIncludeExclude(
  path: string,
  includePatterns: readonly string[],
  excludePatterns: readonly string[],
  options: MatchOptions = {},
): boolean {
  // If exclude patterns exist, check if path matches any - if so, exclude it
  if (excludePatterns.length > 0) {
    for (const pattern of excludePatterns) {
      const matcher = compilePattern(pattern, options);
      if (matcher(path)) {
        return false;
      }
    }
  }

  // If no include patterns, include everything (after exclusion check)
  if (includePatterns.length === 0) {
    return true;
  }

  // Check if path matches any include pattern
  for (const pattern of includePatterns) {
    const matcher = compilePattern(pattern, options);
    if (matcher(path)) {
      return true;
    }
  }

  return false;
}

export function matchesAnyPattern(
  path: string,
  patterns: readonly string[],
  options: MatchOptions = {},
): boolean {
  // Legacy support for old patterns array format
  const { includePatterns, excludePatterns } =
    separateIncludeExcludePatterns(patterns);
  return evaluatePathWithIncludeExclude(
    path,
    includePatterns,
    excludePatterns,
    options,
  );
}

/**
 * Finds first matching rule for path. Processes rules in forward order for top-down precedence.
 */
export function findMatchingRule(
  filePath: string,
  rules: GroupingRule[],
): GroupingRule | null {
  for (const rule of rules) {
    if (
      rule &&
      matchesGroupingRule(filePath, rule, {
        matchBase: true,
        normalizeRelativePaths: true,
      })
    ) {
      return rule;
    }
  }
  return null;
}

export function generateGroupKey(
  filePath: string,
  rule: GroupingRule,
  preferRuleTitle = false,
): string {
  if (preferRuleTitle && rule.title) {
    return rule.title;
  }

  // For new include/exclude format, use the include patterns for title generation
  const includePatterns = normalizePatterns(rule.includeInputs);
  return deriveGroupTitle(
    filePath,
    includePatterns,
    rule.title || DEFAULT_GROUP_NAME,
  );
}

export function createGroupManager<T extends GroupData>(): GroupManager<T> {
  const groups = new Map<string, T>();
  return {
    groups,
    findOrCreateGroup(
      key: string,
      rule: LogicalGroupingRule,
      defaultTitle?: string,
    ): T {
      let group = groups.get(key);
      if (!group) {
        const title = rule.title || defaultTitle || key;
        group = {
          title,
          bytes: 0,
          modules: 0,
          type: 'group',
          icon: rule.icon,
        } as T;
        groups.set(key, group);
      }
      return group;
    },
    getAllGroups(): T[] {
      return [...groups.values()];
    },
    getGroupsWithData(): T[] {
      return [...groups.values()].filter(g => g.bytes > 0);
    },
  };
}

export function toLogicalGroupingRule(rule: GroupingRule): LogicalGroupingRule {
  const { numSegments: maxDepth, ...rest } = rule;
  return { ...rest, maxDepth: 1 };
}

export function findOrCreateGroupFromRule<T extends GroupData>(
  groupManager: GroupManager<T>,
  key: string,
  rule: GroupingRule,
  defaultTitle?: string,
): T {
  const logicalRule = toLogicalGroupingRule(rule);
  return groupManager.findOrCreateGroup(key, logicalRule, defaultTitle);
}

export function processForTable(
  filePath: string,
  rules: GroupingRule[],
  preferRuleTitle = true,
): { rule: GroupingRule | null; groupKey: string | null } {
  const rule = findMatchingRule(filePath, rules);
  if (!rule) {
    return { rule: null, groupKey: null };
  }
  const groupKey = generateGroupKey(filePath, rule, preferRuleTitle);
  return { rule, groupKey };
}

export function extractConcreteSegments(pattern: string): string[] {
  return splitPathSegments(pattern).filter(
    segment => segment !== '**' && segment !== '*' && !segment.includes('*'),
  );
}

export function findSegmentIndex(filePath: string, segment: string): number {
  return splitPathSegments(filePath).indexOf(segment);
}

export function extractPathSlice(
  filePath: string,
  startIndex: number,
  maxDepth?: number,
): string {
  const pathParts = splitPathSegments(filePath);
  const endIndex = maxDepth
    ? Math.min(startIndex + maxDepth, pathParts.length)
    : pathParts.length;
  return pathParts.slice(startIndex, endIndex).join('/');
}

function extractIntelligentGroupKey(
  filePath: string,
  patterns: readonly string[],
  maxDepth: number,
): string {
  const pathParts = splitPathSegments(filePath);

  // Try pattern-based extraction first
  for (const pattern of patterns) {
    const patternKey = extractGroupKeyFromPattern(filePath, pattern, maxDepth);
    if (patternKey) {
      return patternKey;
    }
  }

  // Fallback to simple depth-based extraction from the beginning of path
  if (pathParts.length >= maxDepth) {
    return pathParts.slice(0, maxDepth).join('/');
  }

  // If path is shorter than maxDepth, use the whole path
  return pathParts.join('/');
}

function checkForScopedPackages(paths: string[]): string | null {
  const scopeGroups = new Map<string, number>();
  let totalScopedPaths = 0;
  for (const path of paths) {
    const scopedMatch = path.match(/.*\/@([^/]+)\/[^/]+/);
    if (scopedMatch) {
      const scope = scopedMatch[1];
      if (scope) {
        scopeGroups.set(scope, (scopeGroups.get(scope) || 0) + 1);
        totalScopedPaths++;
      }
    }
  }
  if (totalScopedPaths > paths.length * 0.6) {
    const dominantScope = [...scopeGroups.entries()].sort(
      ([, a], [, b]) => (b as number) - (a as number),
    )[0];
    if (dominantScope && dominantScope[1] > totalScopedPaths * 0.5) {
      return `@${dominantScope[0]}`;
    }
    return 'Scoped Packages';
  }
  return null;
}

function findCommonPath(paths: string[]): string {
  if (paths.length === 0) {
    return DEFAULT_GROUP_NAME;
  }
  if (paths.length === 1) {
    return deriveGroupTitle(paths[0]!, [], DEFAULT_GROUP_NAME);
  }

  const scopedPackagePattern = checkForScopedPackages(paths);
  if (scopedPackagePattern) {
    return scopedPackagePattern;
  }

  const commonRelativePrefix = paths.every(path => path.startsWith('../'))
    ? '../'
    : '';
  const normalizedPaths = paths.map(path => {
    const normalized = path.startsWith('../')
      ? path.replace(/^(\.\.\/)+/, '')
      : path;
    return splitPathSegments(normalized);
  });

  const firstPath = normalizedPaths[0];
  if (!firstPath || firstPath.length === 0) {
    return DEFAULT_GROUP_NAME;
  }

  const commonSegments: string[] = [];
  for (const [i, segment] of firstPath.entries()) {
    if (!segment) {
      continue;
    }
    const isCommonToAll = normalizedPaths.every(
      pathSegments => pathSegments && pathSegments[i] === segment,
    );
    if (isCommonToAll) {
      commonSegments.push(segment);
    } else {
      break;
    }
  }

  if (commonSegments.length > 0) {
    const commonPath = `${commonRelativePrefix + commonSegments.join('/')}/**`;
    if (commonPath.includes('@*/') || commonPath.includes('*/')) {
      return DEFAULT_GROUP_NAME;
    }
    return commonPath;
  }

  const parentDirs = normalizedPaths
    .map(pathSegments => {
      const parentDir =
        pathSegments && pathSegments.length > 0
          ? pathSegments.slice(0, -1).pop()
          : undefined;
      return parentDir || '';
    })
    .filter(dir => dir.length > 0);

  const dirCounts = parentDirs.reduce(
    (acc, dir) => {
      if (dir) {
        acc[dir] = (acc[dir] || 0) + 1;
      }
      return acc;
    },
    {} as Record<string, number>,
  );

  const mostCommonDir = Object.entries(dirCounts).sort(
    ([, a], [, b]) => (b as number) - (a as number),
  )[0]?.[0];
  return mostCommonDir
    ? `${commonRelativePrefix + mostCommonDir}/**`
    : DEFAULT_GROUP_NAME;
}

/**
 * Groups nodes by patterns at current level only. Organizes files into logical groups without recursive processing.
 */
export function applyGrouping(
  nodes: StatsTreeNode[],
  groups: GroupingRule[],
): StatsTreeNode[] {
  if (!groups || groups.length === 0) {
    return [...nodes].sort((a, b) => b.values.bytes - a.values.bytes);
  }

  // Process nodes without recursive grouping - caller handles recursion
  let finalNodes = [...nodes];
  // Track original input nodes vs newly created group nodes
  const originalNodes = new Set(nodes);
  finalNodes.sort((a, b) => b.values.bytes - a.values.bytes);

  for (const group of groups) {
    const {
      title,
      includeInputs,
      excludeInputs,
      icon,
      numSegments: maxDepth,
    } = group;
    const nodesToGroup: StatsTreeNode[] = [];
    const remainingNodes: StatsTreeNode[] = [];

    finalNodes.forEach(node => {
      const matchingRule = findMatchingRule(node.name, [group]);
      if (matchingRule && originalNodes.has(node)) {
        // Only group original input nodes, not previously created group nodes
        nodesToGroup.push(node);
      } else {
        remainingNodes.push(node);
      }
    });

    if (nodesToGroup.length > 0) {
      const groupedNodes: StatsTreeNode[] = [];

      // When reduce is true, always create a single consolidated group
      const shouldCreateSingleGroup = !maxDepth || maxDepth === 0;

      if (!shouldCreateSingleGroup && maxDepth && maxDepth > 0) {
        const pathGroups = new Map<string, StatsTreeNode[]>();
        nodesToGroup.forEach(node => {
          const groupKey = extractIntelligentGroupKey(
            node.name,
            normalizePatterns(includeInputs),
            maxDepth,
          );
          if (!pathGroups.has(groupKey)) {
            pathGroups.set(groupKey, []);
          }
          pathGroups.get(groupKey)!.push(node);
        });

        pathGroups.forEach((nodesInGroup, groupPath) => {
          const totalBytes = nodesInGroup.reduce(
            (sum, node) => sum + node.values.bytes,
            0,
          );
          const totalModules = nodesInGroup.reduce(
            (sum, node) => sum + node.values.modules,
            0,
          );

          const folderNode: StatsTreeNode = {
            name: title || cleanupGroupName(groupPath),
            values: {
              path: groupPath,
              bytes: totalBytes,
              modules: totalModules,
              type: 'group',
              icon,
            },
            children: nodesInGroup.sort(
              (a, b) => b.values.bytes - a.values.bytes,
            ),
          };
          groupedNodes.push(folderNode);
        });
      } else {
        let effectiveTitle: string;
        if (title) {
          effectiveTitle = title;
        } else {
          const samplePath = nodesToGroup[0]?.name || '';
          effectiveTitle = deriveGroupTitle(
            samplePath,
            normalizePatterns(includeInputs),
            DEFAULT_GROUP_NAME,
          );
        }

        const totalBytes = nodesToGroup.reduce(
          (sum, node) => sum + node.values.bytes,
          0,
        );
        const totalModules = nodesToGroup.reduce(
          (sum, node) => sum + node.values.modules,
          0,
        );

        const groupNode: StatsTreeNode = {
          name: effectiveTitle,
          values: {
            path: '',
            bytes: totalBytes,
            modules: totalModules,
            type: 'group',
            icon,
          },
          // When reduce is true, don't show children - collapse to summary only
          children: nodesToGroup.sort(
            (a, b) => b.values.bytes - a.values.bytes,
          ),
        };
        groupedNodes.push(groupNode);
      }

      groupedNodes.sort((a, b) => b.values.bytes - a.values.bytes);
      remainingNodes.push(...groupedNodes);
    }

    finalNodes = remainingNodes;
    finalNodes.sort((a, b) => b.values.bytes - a.values.bytes);
  }

  // Filter out files that are excluded by any group's exclude patterns
  return finalNodes.filter(node => {
    // Keep group nodes (created by grouping process)
    if (!originalNodes.has(node)) {
      return true;
    }

    // For original nodes, check if they're excluded by any group
    return !groups.some(group => {
      if (!group.excludeInputs || group.excludeInputs.length === 0) {
        return false;
      }

      const excludePatterns = normalizePatterns(group.excludeInputs);
      return excludePatterns.some(pattern => {
        const matcher = compilePattern(pattern);
        return matcher(node.name);
      });
    });
  });
}

import { describe, expect, it } from 'vitest';
import type { GroupingRule } from '../../types.js';
import {
  type StatsTreeNode,
  applyGrouping,
  findMatchingRule,
} from './grouping.js';

describe('GroupingRule exclude logic', () => {
  it('should exclude paths that match exclude patterns even when they match include patterns', () => {
    const rule: GroupingRule = {
      includeInputs: '**/node_modules/**',
      excludeInputs: [
        '**/node_modules/react/**',
        '**/node_modules/@angular/**',
      ],
    };

    // These paths match include but should be excluded
    expect(findMatchingRule('node_modules/react/index.js', [rule])).toBeNull();
    expect(
      findMatchingRule('node_modules/@angular/core/index.js', [rule]),
    ).toBeNull();

    // This path matches include and is not excluded
    expect(findMatchingRule('node_modules/lodash/index.js', [rule])).toEqual(
      rule,
    );
  });

  it('should handle multiple exclude patterns', () => {
    const rule: GroupingRule = {
      includeInputs: '**/src/**',
      excludeInputs: ['**/*.test.ts', '**/*.spec.ts', '**/src/legacy/**'],
    };

    // These should be excluded
    expect(findMatchingRule('src/app.test.ts', [rule])).toBeNull();
    expect(findMatchingRule('src/utils.spec.ts', [rule])).toBeNull();
    expect(findMatchingRule('src/legacy/old-code.ts', [rule])).toBeNull();

    // This should match
    expect(findMatchingRule('src/app.ts', [rule])).toEqual(rule);
  });
});

import { minimatch } from 'minimatch';
import type { Issue } from '@code-pushup/models';
import { formatBytes } from '@code-pushup/utils';
import type { BundleStatsConfig } from '../../types.js';
import type {
  UnifiedStats,
  UnifiedStatsBundle,
} from '../../unify/unified-stats.types.js';
import type { BlacklistEntry, BlacklistPatternList } from '../scoring.js';

// ===== PERFORMANCE OPTIMIZATIONS =====

// Cache for blacklist pattern matches to avoid repeated minimatch calls
const BLACKLIST_PATTERN_CACHE = new Map<string, boolean>();

// Clear cache when it gets too large to prevent memory issues
function clearCacheIfNeeded(): void {
  if (BLACKLIST_PATTERN_CACHE.size > 50_000) {
    BLACKLIST_PATTERN_CACHE.clear();
  }
}

// ===== ISSUE ICONS =====

export const ISSUE_ICONS = {
  TOO_LARGE: '🔺',
  TOO_SMALL: '🔻',
  BLACKLIST: '🚫',
} as const;

/**
 * Normalizes blacklist entry to extract pattern string and hint.
 */
function normalizeBlacklistEntry(entry: BlacklistEntry): {
  pattern: string;
  hint?: string;
} {
  if (typeof entry === 'string') {
    return { pattern: entry };
  }
  return { pattern: entry.pattern, hint: entry.hint };
}

/**
 * Optimized pattern matching with caching. Avoids repeated minimatch calls for same path-pattern pairs.
 */
function matchesPattern(path: string, pattern: string): boolean {
  const cacheKey = `${path}|${pattern}`;

  const cached = BLACKLIST_PATTERN_CACHE.get(cacheKey);
  if (cached !== undefined) {
    return cached;
  }

  const result = minimatch(path, pattern, { matchBase: true });
  BLACKLIST_PATTERN_CACHE.set(cacheKey, result);

  return result;
}

/**
 * Checks if a path matches any of the given blacklist patterns. Enables pattern-based filtering with optimized caching.
 */
function matchesBlacklistPattern(
  path: string,
  patterns: BlacklistPatternList,
): { pattern: string; hint?: string } | null {
  // Clear cache periodically to prevent memory bloat
  clearCacheIfNeeded();

  for (const entry of patterns) {
    const { pattern, hint } = normalizeBlacklistEntry(entry);
    if (matchesPattern(path, pattern)) {
      return { pattern, hint };
    }
  }
  return null;
}

/**
 * Creates error issue for oversized artifact exceeding maximum threshold. Indicates unoptimized bundle or accidental check-in requiring optimization.
 *
 * @param outputPath - Path to the output file that exceeds size limit
 * @param bytes - Actual size of the artifact in bytes
 * @param maxSize - Maximum allowed size threshold in bytes
 * @returns Issue object with error severity and optimization recommendation
 *
 * @example
 * ```js
 * createTooLargeIssue('dist/bundle.js', 1048576, 500000)
 * // Returns: { message: "🔺 `dist/bundle.js` is **1 MB** _(> 488 kB)_", severity: 'error', ... }
 * ```
 */
export function createTooLargeIssue(
  outputPath: string,
  bytes: number,
  maxSize: number,
): Issue {
  return {
    message: `${ISSUE_ICONS.TOO_LARGE} \`${outputPath}\` is **${formatBytes(bytes)}** _(> ${formatBytes(maxSize)})_`,
    severity: 'error',
    source: { file: outputPath },
  };
}

/**
 * Creates warning issue for undersized artifact below minimum threshold. Signals missing dependencies or incomplete build requiring verification.
 *
 * @param outputPath - Path to the output file that is below size limit
 * @param bytes - Actual size of the artifact in bytes
 * @param minSize - Minimum expected size threshold in bytes
 * @returns Issue object with warning severity and verification recommendation
 *
 * @example
 * ```js
 * createTooSmallIssue('dist/chunk.js', 512, 2048)
 * // Returns: { message: "🔻 `dist/chunk.js` is **512 B** _(< 2 kB)_", severity: 'warning', ... }
 * ```
 */
export function createTooSmallIssue(
  outputPath: string,
  bytes: number,
  minSize: number,
): Issue {
  return {
    message: `${ISSUE_ICONS.TOO_SMALL} \`${outputPath}\` is **${formatBytes(bytes)}** _(< ${formatBytes(minSize)})_`,
    severity: 'warning',
    source: { file: outputPath },
  };
}

/**
 * Creates error issue for blacklisted import pattern match. Enforces dependency restrictions for security and architectural compliance.
 */
export function createBlacklistedIssue(
  importPath: string,
  outputPath: string,
  pattern: string,
  hint?: string,
): Issue {
  const baseMessage = `${ISSUE_ICONS.BLACKLIST} \`${importPath}\` matches blacklist pattern \`${pattern}\``;
  const message = hint ? `${baseMessage} - ${hint}` : baseMessage;

  return {
    message,
    severity: 'error',
    source: { file: outputPath },
  };
}

/**
 * Validates artifact size against configured thresholds and returns appropriate issues. Ensures bundles stay within acceptable size ranges.
 *
 * @param outputPath - Path to the output file being checked
 * @param output - Output metadata containing size information
 * @param minSize - Minimum expected size threshold in bytes (optional)
 * @param maxSize - Maximum allowed size threshold in bytes (optional)
 * @returns Array of size-related issues found
 */
export function checkSizeIssues(
  outputPath: string,
  output: UnifiedStatsBundle,
  minSize?: number,
  maxSize?: number,
): Issue[] {
  const outputBytes = output.bytes;

  if (maxSize !== undefined && outputBytes > maxSize) {
    return [createTooLargeIssue(outputPath, outputBytes, maxSize)];
  } else if (minSize !== undefined && outputBytes < minSize) {
    return [createTooSmallIssue(outputPath, outputBytes, minSize)];
  }

  return [];
}

/**
 * Scans artifact inputs and imports for blacklisted patterns and returns violation issues.
 * Enforces dependency restrictions across bundle contents.
 *
 * Searches for blacklisted paths in these locations:
 * 1. Primary File Path Locations:
 *    - Object keys in the inputs section
 *    - "path" properties in imports
 *    - "original" properties in imports (exact import statements as written in source code)
 * 2. Entry Point Locations:
 *    - "entryPoint" properties in chunk/output definitions
 * 3. Output File Locations:
 *    - Output file paths (as object keys)
 * 4. Special Path Patterns:
 *    - Disabled paths with "(disabled):" prefix
 *    - Runtime paths with "<runtime>" pattern
 *
 * @param outputPath - Path to the output file being scanned
 * @param output - Output metadata containing inputs and imports
 * @param blacklistPatterns - Array of blacklist patterns (strings or objects with hints)
 * @returns Array of blacklist-related issues found
 */
export function checkBlacklistIssues(
  outputPath: string,
  output: UnifiedStatsBundle,
  blacklistPatterns: BlacklistPatternList,
): Issue[] {
  const issues: Issue[] = [];

  // 1. Check output path itself (object key in outputs section)
  const outputPathMatch = matchesBlacklistPattern(
    outputPath,
    blacklistPatterns,
  );
  if (outputPathMatch) {
    issues.push(
      createBlacklistedIssue(
        outputPath,
        outputPath,
        outputPathMatch.pattern,
        outputPathMatch.hint,
      ),
    );
  }

  // 2. Check entryPoint property
  if (output.entryPoint) {
    const entryPointMatch = matchesBlacklistPattern(
      output.entryPoint,
      blacklistPatterns,
    );
    if (entryPointMatch) {
      issues.push(
        createBlacklistedIssue(
          output.entryPoint,
          outputPath,
          entryPointMatch.pattern,
          entryPointMatch.hint,
        ),
      );
    }
  }

  // 3. Check input paths (object keys in inputs section)
  if (output.inputs) {
    for (const inputPath in output.inputs) {
      const matchedPattern = matchesBlacklistPattern(
        inputPath,
        blacklistPatterns,
      );
      if (matchedPattern) {
        issues.push(
          createBlacklistedIssue(
            inputPath,
            outputPath,
            matchedPattern.pattern,
            matchedPattern.hint,
          ),
        );
      }
    }
  }

  // 4. Check import paths and original import statements
  if (output.imports) {
    for (let i = 0; i < output.imports.length; i++) {
      const importInfo = output.imports[i]!;

      // Check resolved import path
      const importPathMatch = matchesBlacklistPattern(
        importInfo.path,
        blacklistPatterns,
      );
      if (importPathMatch) {
        issues.push(
          createBlacklistedIssue(
            importInfo.path,
            outputPath,
            importPathMatch.pattern,
            importPathMatch.hint,
          ),
        );
      }

      // Check original import statement (exact import as written in source code)
      if (importInfo.original) {
        const originalMatch = matchesBlacklistPattern(
          importInfo.original,
          blacklistPatterns,
        );
        if (originalMatch) {
          issues.push(
            createBlacklistedIssue(
              importInfo.original,
              outputPath,
              originalMatch.pattern,
              originalMatch.hint,
            ),
          );
        }
      }
    }
  }

  return issues;
}

/**
 * Generates comprehensive diagnostic issues for bundle artifacts including size violations and blacklisted imports. Provides actionable feedback for bundle optimization and dependency management.
 *
 * @param statsSlice - Unified bundle statistics containing output files and metadata
 * @param config - Bundle configuration with penalty options and diagnostic thresholds
 * @returns Array of diagnostic issues with severity levels and recommended actions
 */
export function getIssues(
  statsSlice: UnifiedStats,
  config: BundleStatsConfig,
): Issue[] {
  // Clear cache at start of each audit run for clean state
  BLACKLIST_PATTERN_CACHE.clear();

  const issues: Issue[] = [];
  const { penalty = false } = config.scoring || { penalty: false };

  if (!penalty) {
    return issues;
  }

  const blacklistPatterns = penalty?.blacklist;
  const artefactSizeThresholds = penalty?.artefactSize;

  if (!blacklistPatterns?.length && !artefactSizeThresholds) {
    return issues;
  }

  const minArtifactSize = artefactSizeThresholds?.[0];
  const maxArtifactSize = artefactSizeThresholds?.[1];
  const hasBlacklist = blacklistPatterns && blacklistPatterns.length > 0;
  const hasSizeThresholds =
    minArtifactSize !== undefined || maxArtifactSize !== undefined;

  // Track unique blacklisted patterns per bundle to avoid duplicates
  const blacklistedPatterns = new Map<
    string,
    { pattern: string; hint?: string; files: string[]; outputPath: string }
  >();

  for (const outputPath in statsSlice) {
    const output = statsSlice[outputPath]!;

    if (hasSizeThresholds) {
      issues.push(
        ...checkSizeIssues(
          outputPath,
          output,
          minArtifactSize,
          maxArtifactSize,
        ),
      );
    }

    if (hasBlacklist) {
      // Collect blacklisted patterns without creating issues yet
      collectBlacklistedPatterns(
        outputPath,
        output,
        blacklistPatterns,
        blacklistedPatterns,
      );
    }
  }

  // Create unique issues for blacklisted patterns
  for (const [
    patternKey,
    { pattern, hint, files, outputPath },
  ] of blacklistedPatterns) {
    if (files.length === 1) {
      // Single file - show specific file name
      issues.push(createBlacklistedIssue(files[0]!, outputPath, pattern, hint));
    } else {
      // Multiple files - show pattern summary
      const summaryMessage = `Blacklisted modules matching \`${pattern}\` included in file`;
      issues.push(
        createBlacklistedPatternIssue(
          summaryMessage,
          outputPath,
          pattern,
          hint,
          files,
        ),
      );
    }
  }

  return issues;
}

/**
 * Creates error issue for multiple blacklisted files from same pattern. Consolidates multiple violations into single issue.
 */
export function createBlacklistedPatternIssue(
  summaryMessage: string,
  outputPath: string,
  pattern: string,
  hint?: string,
  files?: string[],
): Issue {
  const baseMessage = `${ISSUE_ICONS.BLACKLIST} ${summaryMessage}`;
  const message = hint ? `${baseMessage} - ${hint}` : baseMessage;

  return {
    message,
    severity: 'error',
    source: { file: outputPath },
  };
}

/**
 * Collects blacklisted patterns without creating duplicate issues. Groups by pattern per bundle.
 */
function collectBlacklistedPatterns(
  outputPath: string,
  output: UnifiedStatsBundle,
  blacklistPatterns: BlacklistPatternList,
  blacklistedPatterns: Map<
    string,
    { pattern: string; hint?: string; files: string[]; outputPath: string }
  >,
): void {
  const addToPattern = (
    filePath: string,
    matchResult: { pattern: string; hint?: string },
  ) => {
    const patternKey = `${outputPath}:${matchResult.pattern}`;
    if (blacklistedPatterns.has(patternKey)) {
      const existing = blacklistedPatterns.get(patternKey)!;
      if (!existing.files.includes(filePath)) {
        existing.files.push(filePath);
      }
    } else {
      blacklistedPatterns.set(patternKey, {
        pattern: matchResult.pattern,
        hint: matchResult.hint,
        files: [filePath],
        outputPath,
      });
    }
  };

  // 1. Check output path itself (object key in outputs section)
  const outputPathMatch = matchesBlacklistPattern(
    outputPath,
    blacklistPatterns,
  );
  if (outputPathMatch) {
    addToPattern(outputPath, outputPathMatch);
  }

  // 2. Check entryPoint property
  if (output.entryPoint) {
    const entryPointMatch = matchesBlacklistPattern(
      output.entryPoint,
      blacklistPatterns,
    );
    if (entryPointMatch) {
      addToPattern(output.entryPoint, entryPointMatch);
    }
  }

  // 3. Check input paths (object keys in inputs section)
  if (output.inputs) {
    for (const inputPath in output.inputs) {
      const matchedPattern = matchesBlacklistPattern(
        inputPath,
        blacklistPatterns,
      );
      if (matchedPattern) {
        addToPattern(inputPath, matchedPattern);
      }
    }
  }

  // 4. Check import paths and original import statements
  if (output.imports) {
    for (let i = 0; i < output.imports.length; i++) {
      const importInfo = output.imports[i]!;

      // Check resolved import path
      const importPathMatch = matchesBlacklistPattern(
        importInfo.path,
        blacklistPatterns,
      );
      if (importPathMatch) {
        addToPattern(importInfo.path, importPathMatch);
      }

      // Check original import statement (exact import as written in source code)
      if (importInfo.original) {
        const originalMatch = matchesBlacklistPattern(
          importInfo.original,
          blacklistPatterns,
        );
        if (originalMatch) {
          addToPattern(importInfo.original, originalMatch);
        }
      }
    }
  }
}

