import type { Table } from '@code-pushup/models';
import { formatBytes } from '@code-pushup/utils';
import type { GroupingRule } from '../../types.js';
import type { UnifiedStats } from '../../unify/unified-stats.types.js';
import {
  type GroupData,
  createGroupManager,
  findOrCreateGroupFromRule,
  processForTable,
} from './grouping.js';

const DEFAULT_GROUP_NAME = 'Group';
const REST_GROUP_NAME = 'Rest';

// Performance optimizations: Simple pattern cache only
const PATTERN_MATCH_CACHE = new Map<
  string,
  { rule: GroupingRule | null; groupKey: string | null }
>();

export type SharedViewConfig = {
  enabled?: boolean;
  mode?: 'onlyMatching' | 'all';
};

export type TablePruningConfig = {
  enabled?: boolean;
  maxChildren?: number;
  minSize?: number;
};

export type InsightsTableConfig = SharedViewConfig & {
  groups: GroupingRule[];
  pruning?: TablePruningConfig;
};

/**
 * Simplified aggregation with algorithmic optimizations. Eliminates expensive nested operations and redundant pattern matching.
 */
export function aggregateAndSortGroups(
  statsSlice: UnifiedStats,
  insights: InsightsTableConfig,
): { groups: GroupData[]; restGroup: { title: string; bytes: number } } {
  const groupingRules = insights.groups || [];

  // Early exit optimization
  if (groupingRules.length === 0) {
    const totalBytes = Object.values(statsSlice).reduce(
      (acc, { bytes }) => acc + bytes,
      0,
    );
    return {
      groups: [],
      restGroup: { bytes: totalBytes, title: REST_GROUP_NAME },
    };
  }

  const groupManager = createGroupManager<GroupData>();
  PATTERN_MATCH_CACHE.clear();

  // Pre-create all possible groups to avoid repeated lookups
  const preCreatedGroups = new Map<string, GroupData>();
  for (const rule of groupingRules) {
    const effectiveTitle = rule.title || DEFAULT_GROUP_NAME;
    const group = findOrCreateGroupFromRule(
      groupManager,
      effectiveTitle,
      rule,
      effectiveTitle,
    );
    preCreatedGroups.set(effectiveTitle, group);
  }

  let totalRestBytes = 0;
  const outputEntries = Object.entries(statsSlice);

  // Single-pass processing: collect all inputs first, then process in batch
  const inputsToProcess: {
    inputPath: string;
    inputBytes: number;
    outputKey: string;
  }[] = [];

  for (const [outputKey, output] of outputEntries) {
    totalRestBytes += output.bytes;

    if (output.inputs) {
      for (const [inputPath, input] of Object.entries(output.inputs)) {
        if (input.bytes > 0) {
          inputsToProcess.push({
            inputPath,
            inputBytes: input.bytes,
            outputKey,
          });
        }
      }
    }
  }

  // Process all inputs in single optimized loop with early termination
  const outputBytesConsumed = new Map<string, number>();
  const processedInputs = new Set<string>(); // Track inputs that have been fully consumed

  for (const { inputPath, inputBytes, outputKey } of inputsToProcess) {
    // Skip inputs that have already been fully processed by a previous rule
    if (processedInputs.has(inputPath)) {
      continue;
    }

    // Use cached pattern matching
    let matchResult = PATTERN_MATCH_CACHE.get(inputPath);
    if (!matchResult) {
      matchResult = processForTable(inputPath, groupingRules, true);
      PATTERN_MATCH_CACHE.set(inputPath, matchResult);
    }

    const { rule, groupKey } = matchResult;
    if (rule && groupKey) {
      // Use pre-created group or create new
      let group = preCreatedGroups.get(groupKey);
      if (!group) {
        group = findOrCreateGroupFromRule(
          groupManager,
          groupKey,
          rule,
          rule.title || groupKey,
        );
        preCreatedGroups.set(groupKey, group);
      }

      group.bytes += inputBytes;
      group.modules += 1;

      // Track consumed bytes per output
      const consumed = outputBytesConsumed.get(outputKey) || 0;
      outputBytesConsumed.set(outputKey, consumed + inputBytes);
      totalRestBytes -= inputBytes;

      // Mark input as fully processed - no need to check it against other patterns
      processedInputs.add(inputPath);
    }
  }

  // Process remaining output bytes efficiently, skipping outputs with no remaining bytes
  for (const [outputKey, output] of outputEntries) {
    const consumedBytes = outputBytesConsumed.get(outputKey) || 0;
    const remainingBytes = output.bytes - consumedBytes;

    // Skip outputs that have been fully consumed by input processing
    if (remainingBytes <= 0) {
      continue;
    }

    let matchResult = PATTERN_MATCH_CACHE.get(outputKey);
    if (!matchResult) {
      matchResult = processForTable(outputKey, groupingRules, true);
      PATTERN_MATCH_CACHE.set(outputKey, matchResult);
    }

    const { rule, groupKey } = matchResult;
    if (rule && groupKey) {
      let group = preCreatedGroups.get(groupKey);
      if (!group) {
        group = findOrCreateGroupFromRule(
          groupManager,
          groupKey,
          rule,
          rule.title || groupKey,
        );
        preCreatedGroups.set(groupKey, group);
      }
      group.bytes += remainingBytes;
      totalRestBytes -= remainingBytes;
    }
  }

  const restGroup = {
    bytes: Math.max(0, totalRestBytes),
    title: REST_GROUP_NAME,
  };

  const groups = groupManager.getGroupsWithData();

  // Optimized sorting - only sort if we have multiple groups
  if (groups.length > 1) {
    groups.sort((a, b) => b.bytes - a.bytes);
  }

  return { groups, restGroup };
}

/**
 * Transforms aggregated group data into table format. Creates table rows from group statistics.
 */
export function createTable(
  groups: GroupData[],
  restGroup: { title: string; bytes: number },
  viewMode: 'onlyMatching' | 'all' = 'onlyMatching',
  pruning?: TablePruningConfig,
): Table {
  const rows: { group: string; modules: string; size: string }[] = [];

  let processedGroups = groups;
  let processedRestGroup = restGroup;

  // Apply pruning if enabled
  if (pruning?.enabled) {
    const { minSize = 0, maxChildren } = pruning;

    // Filter groups by minimum size
    const keptGroups: GroupData[] = [];
    const prunedGroups: GroupData[] = [];

    for (const group of groups) {
      if (group.bytes >= minSize) {
        keptGroups.push(group);
      } else {
        prunedGroups.push(group);
      }
    }

    // Apply maxChildren limit
    let finalGroups = keptGroups;
    if (maxChildren && keptGroups.length > maxChildren) {
      finalGroups = keptGroups.slice(0, maxChildren);
      const excessGroups = keptGroups.slice(maxChildren);
      prunedGroups.push(...excessGroups);
    }

    // Add pruned groups to rest
    if (prunedGroups.length > 0) {
      const prunedBytes = prunedGroups.reduce(
        (sum, group) => sum + group.bytes,
        0,
      );
      processedRestGroup = {
        title: REST_GROUP_NAME,
        bytes: restGroup.bytes + prunedBytes,
      };
    }

    processedGroups = finalGroups;
  }

  for (const group of processedGroups) {
    // Apply viewMode filtering
    if (viewMode === 'onlyMatching' && group.bytes === 0) {
      continue;
    }

    rows.push({
      group: group.icon ? `${group.icon} ${group.title}` : group.title,
      modules: group.modules.toString(),
      size: formatBytes(group.bytes),
    });
  }

  // Apply viewMode filtering to rest group
  if (processedRestGroup.bytes > 0 || viewMode === 'all') {
    rows.push({
      group: 'Rest',
      modules: '-',
      size: formatBytes(processedRestGroup.bytes),
    });
  }

  return {
    columns: [
      { key: 'group', label: 'Group', align: 'left' },
      { key: 'modules', label: 'Modules', align: 'right' },
      { key: 'size', label: 'Size', align: 'right' },
    ],
    rows,
  };
}

/**
 * Creates insights table from stats and grouping rules. Combines aggregation and table formatting.
 */
export function createInsightsTable(
  statsSlice: UnifiedStats,
  insights: InsightsTableConfig,
): Table {
  const { groups, restGroup } = aggregateAndSortGroups(statsSlice, insights);
  return createTable(
    groups,
    restGroup,
    insights.mode || 'onlyMatching',
    insights.pruning,
  );
}

import type { BasicTree, BasicTreeNode } from '@code-pushup/models';
import { formatBytes, pluralizeToken, truncateText } from '@code-pushup/utils';
import type { GroupingRule } from '../../types.js';
import type { UnifiedStats } from '../../unify/unified-stats.types';
import type { SelectionConfig } from '../selection.js';
import {
  type StatsTreeNode,
  applyGrouping as applyGroupingAndSort,
} from './grouping.js';
import type { SharedViewConfig } from './table.js';
import type { StatsNodeValues } from './types.js';

/**
 * Helper type that transforms picked properties by adding "Display" suffix and making them strings.
 */
export type AddDisplaySuffix<T> = {
  [K in keyof T as `${string & K}Display`]: string;
};

/**
 * Display values for StatsTreeNode with formatted strings.
 */
export type StatsTreeNodeDisplayValues = AddDisplaySuffix<
  Pick<StatsNodeValues, 'bytes' | 'modules' | 'path'>
>;

export type FormattedStatsTreeNode = {
  name: string;
  values?: Record<string, string | number>;
  children: FormattedStatsTreeNode[];
};

/**
 * Display tree structure for bundle statistics output.
 */
export type FormattedStatsTree = {
  root: FormattedStatsTreeNode;
};

export const DEFAULT_PATH_LENGTH = 40;

// Simple performance optimization: single cache for formatted strings
const STRING_FORMAT_CACHE = new Map<string, string>();

export type DependencyTreeConfig = {
  groups?: GroupingRule[] | false;
  pruning?: PruningConfig;
} & SharedViewConfig;

export type PruningConfig = {
  enabled?: boolean;
  maxChildren?: number;
  maxDepth?: number;
  minSize?: number;
  pathLength?: number | false;
};

export type PruneTreeNode = {
  children: StatsTreeNode[];
};

/**
 * Converts statistics to tree structure. Streamlined for speed.
 */
export function convertStatsToTree(stats: UnifiedStats): StatsTreeNode[] {
  const artifacts = Object.values(stats);
  const result: StatsTreeNode[] = [];

  for (const artefact of artifacts) {
    const isEntry = Boolean(artefact.entryPoint);
    let inputNodes: StatsTreeNode[] = [];

    if (artefact.inputs) {
      const validInputs: StatsTreeNode[] = [];

      for (const [path, input] of Object.entries(artefact.inputs)) {
        if (input.bytes > 0) {
          validInputs.push({
            name: path,
            values: {
              path,
              bytes: input.bytes,
              modules: 1,
              type: 'static-import',
            },
            children: [],
          });
        }
      }

      if (validInputs.length > 1) {
        validInputs.sort((a, b) => b.values.bytes - a.values.bytes);
      }
      inputNodes = validInputs;
    }

    result.push({
      name: artefact.path,
      values: {
        path: artefact.path,
        bytes: artefact.bytes,
        modules: inputNodes.length,
        type: isEntry ? 'entry-file' : 'static-import',
      },
      children: inputNodes,
    });
  }

  if (result.length > 1) {
    result.sort((a, b) => b.values.bytes - a.values.bytes);
  }

  return result;
}

/**
 * Flattens single-child groups to reduce hierarchy and applies group icons to actual files.
 */
function flattenSingleChildGroups(nodes: StatsTreeNode[]): StatsTreeNode[] {
  return nodes.map(node => {
    // If this is a group with exactly one child, flatten it
    if (node.values.type === 'group' && node.children.length === 1) {
      const child = node.children[0]!;

      // Use the group's icon for the child file if the group has an icon
      return {
        ...child,
        values: {
          ...child.values,
          icon: node.values.icon, // Use group icon only if it exists
        },
        children: flattenSingleChildGroups(child.children), // Recursively flatten children
      };
    }

    // For other nodes, just recursively process children
    return {
      ...node,
      children: flattenSingleChildGroups(node.children),
    };
  });
}

/**
 * Formats tree nodes with clean names and separate values for proper alignment.
 */
export function formatStatsTreeForDisplay(
  node: StatsTreeNode,
  pathLength: number | false = DEFAULT_PATH_LENGTH,
): FormattedStatsTreeNode {
  const maxChars = pathLength === false ? DEFAULT_PATH_LENGTH : pathLength;

  // Clean name truncation (no icons or size info)
  const cleanName =
    maxChars < node.name.length
      ? truncateText(node.name, { maxChars, position: 'middle' })
      : node.name;

  // Use only explicitly configured icons
  const icon = node.values.icon;

  // Recurse through children (keep it simple - recursion is fast in JS)
  const children = node.children.map(child =>
    formatStatsTreeForDisplay(child, pathLength),
  );

  const values: Record<string, string | number> = {};

  // Show size for all nodes except intermediate nodes in single-child chains
  // This means: entry files, groups with multiple children, and leaf files all show size
  if (node.children.length !== 1) {
    values['size'] = formatBytes(node.values.bytes);
  }

  // Only show source count if more than 1 source
  if (node.values.modules > 1) {
    // For "..." groups that represent multiple files, show "files" instead of "sources"
    const token = node.name === '...' ? 'file' : 'module';
    values['modules'] = pluralizeToken(token, node.values.modules);
  }

  return {
    name: icon ? `${icon} ${cleanName}` : cleanName,
    values,
    children,
  };
}

/**
 * Converts FormattedStatsTreeNode to BasicTreeNode for proper ASCII display.
 */
function formattedStatsTreeNodeToBasicTreeNode(
  node: FormattedStatsTreeNode,
): BasicTreeNode {
  return {
    name: node.name,
    ...(node.values && { values: node.values }),
    ...(node.children.length > 0 && {
      children: node.children.map(formattedStatsTreeNodeToBasicTreeNode),
    }),
  };
}

/**
 * Creates artifact tree with focused optimizations.
 */
export function createTree(
  statsSlice: UnifiedStats,
  options: {
    title: string;
    selection?: SelectionConfig;
  } & DependencyTreeConfig,
): BasicTree {
  const { title, groups, pruning, mode, selection } = options;

  // Simple cache management
  if (STRING_FORMAT_CACHE.size > 25_000) {
    STRING_FORMAT_CACHE.clear();
  }

  let nodes = convertStatsToTree(statsSlice);

  // Apply grouping if needed
  if (Array.isArray(groups) && groups.length > 0 && nodes.length > 0) {
    // Apply grouping only to inputs (children) within each output file
    // Don't group the output files themselves
    for (const node of nodes) {
      if (node.children.length > 0) {
        node.children = applyGroupingAndSort(node.children, groups);
      }
    }

    // Flatten single-child groups after applying grouping
    nodes = flattenSingleChildGroups(nodes);
  }

  // Apply onlyMatching mode filtering - hide files with no matching inputs
  if (mode === 'onlyMatching') {
    nodes = nodes.filter(node => node.children.length > 0);
  }

  // Apply pruning only if explicitly configured and enabled
  let prunedNodes: StatsTreeNode[];
  if (pruning && pruning.enabled !== false) {
    const prunedRoot = pruneTree({ children: nodes }, pruning);
    prunedNodes = prunedRoot.children;
  } else {
    // No pruning - show all nodes
    prunedNodes = nodes;
  }

  // Calculate totals
  let totalBytes = 0;
  let totalModules = 0;
  for (const node of prunedNodes) {
    totalBytes += node.values.bytes;
    totalModules += node.values.modules;
  }

  // Format nodes
  const formattedChildren = prunedNodes.map(node =>
    formatStatsTreeForDisplay(node, pruning?.pathLength),
  );

  const formattedRoot: FormattedStatsTreeNode = {
    name: title,
    values: {
      'total size': formatBytes(totalBytes),
      ...(totalModules > 1 && { 'total modules': totalModules }),
      files: prunedNodes.length,
    },
    children: formattedChildren,
  };

  // Convert to BasicTree for proper ASCII display
  const root = formattedStatsTreeNodeToBasicTreeNode(formattedRoot);

  return {
    type: 'basic',
    title,
    root,
  };
}

export function pruneTree(
  rootNode: PruneTreeNode,
  options: PruningConfig,
): PruneTreeNode {
  // Provide defaults for all required properties
  const completeOptions: Required<PruningConfig> = {
    maxDepth: options.maxDepth ?? 999,
    maxChildren: options.maxChildren ?? 999,
    minSize: options.minSize ?? 0,
    pathLength: options.pathLength ?? 999,
    enabled: options.enabled ?? true,
  };

  // Start from 1 so that maxDepth: 2 stops at package level, maxDepth: 3 shows individual files
  return pruneTreeRecursive(rootNode, completeOptions, 1);
}

function pruneTreeRecursive(
  node: PruneTreeNode,
  options: Required<PruningConfig>,
  currentDepth: number,
): PruneTreeNode {
  const { maxChildren, maxDepth, minSize } = options;

  if (node.children.length === 0) {
    return node;
  }

  // Sort children by size (largest first)
  if (node.children.length > 1) {
    node.children.sort((a, b) => b.values.bytes - a.values.bytes);
  }

  // Apply maxChildren and minSize filtering at all levels within maxDepth
  const keptChildren: StatsTreeNode[] = [];
  const groupedChildren: StatsTreeNode[] = [];

  for (const child of node.children) {
    if (child.values.bytes >= minSize) {
      // Recursively prune child's subtree if within maxDepth
      const prunedChild =
        currentDepth < maxDepth
          ? pruneTreeRecursive(
              { children: child.children },
              options,
              currentDepth + 1,
            )
          : { children: [] };

      keptChildren.push({
        ...child,
        children: prunedChild.children,
      });
    } else {
      // Collect small files for grouping
      groupedChildren.push(child);
    }
  }

  // Apply maxChildren limit - move overflow to grouped items
  let finalChildren = keptChildren;
  if (keptChildren.length > maxChildren) {
    const kept = keptChildren.slice(0, maxChildren);
    const overflow = keptChildren.slice(maxChildren);

    // Add overflow files to the grouped items
    groupedChildren.push(...overflow);
    finalChildren = kept;
  }

  // Create "..." group if we have multiple items to represent, or show single item directly
  if (groupedChildren.length > 0) {
    if (groupedChildren.length === 1) {
      // If there's only one grouped item, show it directly instead of creating "..." group
      finalChildren.push(groupedChildren[0]!);
    } else {
      // Multiple items - create "..." group
      const totalBytes = groupedChildren.reduce(
        (sum, child) => sum + child.values.bytes,
        0,
      );
      const totalModules = groupedChildren.reduce(
        (sum, child) => sum + child.values.modules,
        0,
      );

      const moreNode = {
        name: '...',
        values: {
          path: '',
          bytes: totalBytes,
          modules: totalModules,
          type: 'group' as const,
        },
        children: [], // Empty - just represents the grouped items
      };

      finalChildren.push(moreNode);
    }
  }

  return { children: finalChildren };
}

